package org.apache.commons.math.estimation;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.linear.InvalidMatrixException;
import org.apache.commons.math.linear.RealMatrixImpl;
import org.apache.commons.math3.exception.InvalidMatrixException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

/**
 * Unit tests for AbstractEstimator.getCovariances
 */
public class AbstractEstimator_getCovariances_TriageGen1Test {

    private TestEstimator estimator;
    private EstimationProblem mockProblem;

    /**
     * Concrete implementation of AbstractEstimator for testing purposes
     * since the class is abstract.
     */
    private static class TestEstimator extends AbstractEstimator {
        public double[][] jacobian;

        protected TestEstimator() {
            super();
        }

        @Override
        protected void updateJacobian() {
            // In a real scenario this would populate this.jacobian
            // For testing, we will set it manually in the test
        }

        @Override
        public void estimate(EstimationProblem problem) throws EstimationException {
            // No-op for covariance testing
        }

        // Expose jacobian for test manipulation
        public void setJacobian(double[][] jacobian) {
            this.jacobian = jacobian;
        }
    }

    @Before
    public void setUp() {
        estimator = new TestEstimator();
        mockProblem = mock(EstimationProblem.class);
    }

    @Test
    public void testGetCovariances_Success() throws EstimationException {
        // Setup: 2 parameters, 3 measurements
        // Jacobian J (3x2)
        // [ 1, 0 ]
        // [ 0, 1 ]
        // [ 1, 1 ]
        double[][] jacobianData = {
            1.0, 0.0,
            0.0, 1.0,
            1.0, 1.0
        };
        estimator.setJacobian(jacobianData);

        when(mockProblem.getMeasurements()).thenReturn(new double[]{0.1, 0.2, 0.3});
        when(mockProblem.getAllParameters()).thenReturn(new double[]{0.0, 0.0});

        // Calculation:
        // J^T * J:
        // [ (1*1 + 0*0 + 1*1), (1*0 + 0*1 + 1*1) ] => [ 2, 1 ]
        // [ (0*1 + 1*0 + 1*1), (0*0 + 1*1 + 1*1) ] => [ 1, 2 ]
        // Inverse of [2, 1; 1, 2]:
        // det = 4 - 1 = 3
        // Inv = 1/3 * [ 2, -1; -1, 2 ] = [ 0.666..., -0.333...; -0.333..., 0.666... ]

        double[][] result = estimator.getCovariances(mockProblem);

        double delta = 1e-10;
        assertEquals(0.6666666666666666, result[0][0], delta);
        assertEquals(-0.3333333333333333, result[0][1], delta);
        assertEquals(-0.3333333333333333, result[1][0], delta);
        assertEquals(0.6666666666666666, result[1][1], delta);
    }

    @Test(expected = EstimationException.class)
    public void testGetCovariances_SingularMatrix() throws EstimationException {
        // Setup: 2 parameters, 2 measurements
        // Jacobian J (2x2)
        // [ 1, 1 ]
        // [ 1, 1 ]
        // This will result in a singular J^T * J
        double[][] jacobianData = {
            1.0, 1.0,
            1.0, 1.0
        };
        estimator.setJacobian(jacobianData);

        when(mockProblem.getMeasurements()).thenReturn(new double[]{0.1, 0.2});
        when(mockProblem.getAllParameters()).thenReturn(new double[]{0.0, 0.0});

        estimator.getCovariances(mockProblem);
    }

    @Test
    public void testGetCovariances_SingleParameter() throws EstimationException {
        // Setup: 1 parameter, 2 measurements
        // J (2x1)
        // [ 2 ]
        // [ 3 ]
        double[][] jacobianData = {
            2.0,
            3.0
        };
        estimator.setJacobian(jacobianData);

        when(mockProblem.getMeasurements()).thenReturn(new double[]{0.1, 0.2});
        when(mockProblem.getAllParameters()).thenReturn(new double[]{0.0});

        // J^T * J = [ 2*2 + 3*3 ] = [ 13 ]
        // Inverse = [ 1/13 ] = [ 0.07692307692307693 ]

        double[][] result = estimator.getCovariances(mockProblem);

        assertEquals(1, result.length);
        assertEquals(1, result[0].length);
        assertEquals(1.0 / 13.0, result[0][0], 1e-15);
    }
}
